Item.method_code:
Innovator innovator = this.getInnovator();
string orderString = this.getProperty("order");
string[] favorites = orderString.Split(",");
int favoriteOrder = 128;
foreach (string favoriteId in favorites)
{
	Item editedFavorite = innovator.newItem("Favorite", "edit");
	editedFavorite.setID(favoriteId);
	editedFavorite.setProperty("favorite_order", favoriteOrder.ToString(CultureInfo.InvariantCulture));
	editedFavorite.apply();
	favoriteOrder += 128;
}

return innovator.newResult("OK");
